 public string UnitType {get;set;}="Non-IU";
 public bool HasBankAccount {get;set;}=true;
 public string Operation {get;set;}="School-managed";
 public string SchoolHead {get;set;}="";
 public string Designation {get;set;}="School Head";
 public string PreparedBy {get;set;}="";
 public string Superintendent {get;set;}="Marites A. Ibañez, CESO V";
 public string BankName {get;set;}="";
 public string BankAccountLabel {get;set;}="";
 public string BankAccount {get;set;}="";
 public string Detail {get;set;}="Detailed";
 public List<string> CashAccounts {get;set;}=[];
 public List<string> InventoryAccounts {get;set;}=[];
 public List<string> CostAccounts {get;set;}=[];
 public List<string> InvestingAccounts {get;set;}=[];
 public List<string> FinancingAccounts {get;set;}=[];
 public string FocalPerson=>UnitType=="IU"?"Eureka Shane Alpha P. Bool":District switch{"I"=>"Chubasco R. Ramirez","II"=>"Ma. Ellaine Sairel R. Magpantay","III"=>"Abegail Ivy C. Perez","IV"=>"Jhece Mae C. Agelion",_=>"Accounting Section"};
 public static SchoolProfile Default(Database db){string? Code(string name)=>db.Accounts.FirstOrDefault(a=>a.Level==8&&a.Name==name)?.Code; List<string> Codes(params string[] names)=>names.Select(Code).OfType<string>().ToList();return new(){BankAccount=Code("Cash in bank")??"",CashAccounts=Codes("Cash in bank"),InventoryAccounts=Codes("Inventory"),CostAccounts=Codes("Cost of goods sold"),InvestingAccounts=Codes("Property and equipment"),FinancingAccounts=Codes("Owner capital")};}
}
record CanteenInput(string Id,string Kind,DateOnly Date,string Name,string Reference,decimal Amount,decimal Quantity,decimal UnitCost,string Details,string Classification,string SeriesFrom,string SeriesTo,int Count,string? BankId=null);
