record ReportDefinition(string Id,string Title,string Category,string Description,string Source,string Rule="Always");
record ReportListing(string Id,string Title,string Category,string Description,string Source,bool Applicable,string? Reason,DateOnly PeriodStart,DateOnly PeriodEnd,DateOnly DueDate,string Readiness);
