 public static void ValidateProfile(Database db,SchoolProfile p){
  if(string.IsNullOrWhiteSpace(p.Name)||!new[]{"IU","Non-IU"}.Contains(p.UnitType)||!new[]{"School-managed","Cooperative","Laboratory"}.Contains(p.Operation)||!new[]{"I","II","III","IV"}.Contains(p.District)||!new[]{"Detailed","Condensed"}.Contains(p.Detail))throw new ArgumentException("Provide a school name and valid school/report settings.");
  foreach(var code in p.CashAccounts.Concat(p.InventoryAccounts).Concat(p.CostAccounts).Concat(p.InvestingAccounts).Concat(p.FinancingAccounts).Append(p.BankAccount).Where(c=>c!=""))if(!db.Accounts.Any(a=>a.Level==8&&a.Code==code))throw new ArgumentException("Report mappings must use existing posting accounts.");
  if(p.CashAccounts.Concat(p.InventoryAccounts).Any(c=>db.Accounts.Single(a=>a.Code==c).Category!="Asset")||p.CostAccounts.Any(c=>db.Accounts.Single(a=>a.Code==c).Category!="Expense"))throw new ArgumentException("Cash/inventory mappings need asset accounts; cost mappings need expense accounts.");
  if(p.HasBankAccount&&!p.CashAccounts.Contains(p.BankAccount))throw new ArgumentException("Select a bank posting account within your cash-account mappings.");
  if(p.CashAccounts.Count==0)throw new ArgumentException("Map at least one cash account.");
  if(p.CashAccounts.Distinct().Count()!=p.CashAccounts.Count||p.CashAccounts.Intersect(p.InvestingAccounts.Concat(p.FinancingAccounts)).Any()||p.InvestingAccounts.Intersect(p.FinancingAccounts).Any())throw new ArgumentException("Cash, investing and financing mappings must not overlap.");
 }
 public static void ValidateInput(CanteenInput input){
  if(!InputKinds.Contains(input.Kind)||string.IsNullOrWhiteSpace(input.Name)||input.Date==default)throw new ArgumentException("Select an input type, date and description.");
  if(decimal.Round(input.Amount,2)!=input.Amount||input.Quantity<0||input.UnitCost<0||input.Count<0)throw new ArgumentException("Use two-decimal amounts and nonnegative quantities, costs and counts.");
  if(input.Kind!="Bank statement balance"&&input.Amount<0)throw new ArgumentException("This input requires a nonnegative amount.");
  if(input.Kind.StartsWith("Inventory ")&&(input.Quantity<=0||string.IsNullOrWhiteSpace(input.Reference)))throw new ArgumentException("Stock movements require a positive quantity and source-document reference; description is the item name.");
  if(input.Kind=="Collection/deposit detail"&&(!new[]{"Collection","Deposit"}.Contains(input.Classification)||string.IsNullOrWhiteSpace(input.Reference)))throw new ArgumentException("Select Collection or Deposit and enter the source receipt/deposit reference.");
  if(input.Kind=="Cash-flow classification"&&(!new[]{"Operating","Investing","Financing"}.Contains(input.Classification)||string.IsNullOrWhiteSpace(input.Reference)))throw new ArgumentException("Select a cash-flow classification and posted document reference.");
 }
 static bool Applicable(ReportDefinition d,SchoolProfile p)=>d.Rule switch{"Bank"=>p.HasBankAccount,"Non-IU bank"=>p.UnitType=="Non-IU"&&p.HasBankAccount,"Non-IU cash"=>p.UnitType=="Non-IU"&&!p.HasBankAccount,"IU"=>p.UnitType=="IU","Cooperative"=>p.Operation=="Cooperative","Laboratory"=>p.Operation=="Laboratory",_=>true};
 static (DateOnly start,DateOnly end,DateOnly due) Period(ReportDefinition d,DateOnly month){var quarterly=d.Category=="A-1"||d.Id=="transmittal-a1";var start=new DateOnly(month.Year,quarterly?((month.Month-1)/3)*3+1:month.Month,1);var end=start.AddMonths(quarterly?3:1).AddDays(-1);var dueMonth=quarterly?end.AddMonths(2):end.AddDays(1);return(start,end,new DateOnly(dueMonth.Year,dueMonth.Month,quarterly?15:10));}
 public static List<ReportListing> Catalog(Database db,DateOnly month){var p=db.CanteenProfile??SchoolProfile.Default(db);return Definitions.Select(d=>{var(start,end,due)=Period(d,month);var applicable=Applicable(d,p);return new ReportListing(d.Id,d.Title,d.Category,d.Description,d.Source,applicable,applicable?null:$"Applies to {d.Rule.ToLowerInvariant()} schools only.",start,end,due,d.Source.Contains("+")?"Ledger + records":d.Source.Contains("ledger",StringComparison.OrdinalIgnoreCase)||d.Source=="Posted documents"?"Ledger-derived":"Additional records");}).ToList();}
 public static CanteenReport Build(Database db,string id,DateOnly month,string? detail=null,string? bankId=null){
  var def=Definitions.SingleOrDefault(d=>d.Id==id)??throw new ArgumentException("Unknown canteen report.");var p=db.CanteenProfile??SchoolProfile.Default(db);if(bankId is not null&&id!="bank-reconciliation")throw new ArgumentException("Bank selection applies to bank reconciliation only.");
  BankAccount? bank=null;if(id=="bank-reconciliation"){bank=Banking.Resolve(db,bankId);if(bank is not null){p=System.Text.Json.JsonSerializer.Deserialize<SchoolProfile>(System.Text.Json.JsonSerializer.Serialize(p))!;p.BankAccount=bank.GlAccount;p.BankName=bank.Name+" · "+bank.Branch;p.BankAccountLabel=bank.AccountNumber;if(bankId is not null)p.HasBankAccount=true;}}
  if(!Applicable(def,p))throw new ArgumentException("This report does not apply to the selected school profile.");
  if(detail is not null&&!new[]{"Detailed","Condensed"}.Contains(detail))throw new ArgumentException("Select Detailed or Condensed statement format.");
  var(start,end,due)=Period(def,month);var report=new CanteenReport{Id=id,Title=def.Title,Category=def.Category,School=p.Name,SchoolId=p.SchoolId,SubOffice=p.SubOffice,Profile=$"{p.UnitType} · {(p.HasBankAccount?"With bank account":"Without bank account")} · {p.Operation}",PeriodStart=start,PeriodEnd=end,DueDate=due,PreparedBy=p.PreparedBy,SchoolHead=p.SchoolHead};
  if(new[]{"position","performance","cash-flows","income-statement"}.Contains(id))report.Title=(detail??p.Detail)+" "+report.Title;
  if(string.IsNullOrWhiteSpace(p.SchoolId)||string.IsNullOrWhiteSpace(p.SchoolHead)||string.IsNullOrWhiteSpace(p.PreparedBy))report.Warnings.Add("Complete the school ID, prepared-by and school-head fields before submission.");
  var posted=db.Documents.Where(d=>d.Status=="Posted"&&d.Date<=end).OrderBy(d=>d.Date).ThenBy(d=>d.Number).ToList();var docs=posted.Where(d=>d.Date>=start).ToList();var accounts=db.Accounts.Where(a=>a.Level==8).ToList();var all=posted.SelectMany(d=>d.Lines.Select(l=>new Entry(d,l,l.CardId??d.CardId))).ToList();var entries=all.Where(e=>e.D.Date>=start).ToList();var inputs=db.CanteenInputs.Where(i=>i.Date>=start&&i.Date<=end).OrderBy(i=>i.Date).ToList();
  string Name(string code)=>db.Accounts.FirstOrDefault(a=>a.Code==code)?.Name??code;string Card(string? card)=>db.Cards.FirstOrDefault(c=>c.Id==card)?.Name??"Unassigned";
  decimal Balance(string code,bool opening=false)=>all.Where(e=>e.L.Account==code&&(!opening||e.D.Date<start)).Sum(e=>e.L.Debit-e.L.Credit);
