  object?[] R(params object?[] cells)=>cells;
  void Warn(string text){if(!report.Warnings.Contains(text))report.Warnings.Add(text);}
  void Evidence(string kind,string title){var rows=inputs.Where(i=>i.Kind==kind).ToList();if(rows.Count==0)Warn($"No {kind.ToLowerInvariant()} records entered for this period; enter records or document a nil activity in the notes.");Section(title,["Date","Description","Reference","Amount / PHP","Details"],rows.Select(i=>R(i.Date.ToString("yyyy-MM-dd"),i.Name,i.Reference,i.Amount,i.Details)));}
  switch(id){
   case "position":{
    var condensed=(detail??p.Detail)=="Condensed";foreach(var category in new[]{"Asset","Liability","Equity"}){var sign=category=="Asset"?1:-1;var rows=accounts.Where(a=>a.Category==category).Select(a=>R(a.Name,Balance(a.Code)*sign)).ToList();var total=rows.Sum(r=>(decimal)r[1]!);if(category=="Equity"){var earnings=-accounts.Where(a=>a.Category is "Revenue" or "Expense").Sum(a=>Balance(a.Code));rows.Add(R("Accumulated/current surplus from posted income and expenses",earnings));total+=earnings;}Section(category,["Account / classification","PHP"],condensed?[R("Total "+category,total)]:rows.Append(R("TOTAL "+category.ToUpperInvariant(),total)));}
    var difference=accounts.Sum(a=>Balance(a.Code));if(difference!=0)Warn("Statement is out of balance by PHP "+difference.ToString("N2"));report.Narrative.Add("Equity labels follow the configured chart. Map the school's approved GAM accounts before statutory submission; this sample chart is generic.");break;}
   case "performance":{
