    List<object?[]> Rows(IEnumerable<Account> chosen,int sign)=>chosen.Select(a=>R(a.Name,entries.Where(e=>e.L.Account==a.Code).Sum(e=>e.L.Debit-e.L.Credit)*sign)).ToList();
    var revenues=Rows(accounts.Where(a=>a.Category=="Revenue"),-1);var costs=Rows(accounts.Where(a=>p.CostAccounts.Contains(a.Code)),1);var expenses=Rows(accounts.Where(a=>a.Category=="Expense"&&!p.CostAccounts.Contains(a.Code)),1);
