   case "notes":report.Narrative.Add("Reporting entity: "+p.Name+". Basis: posted double-entry ledger for the stated period, with separately recorded bank, stock and supporting-document information.");report.Narrative.Add("These adapted statements do not assert full GAM/COA compliance. Verify the approved chart, accounting policies, cut-offs, taxes and disclosures with the Accounting Unit.");Evidence("Financial statement note","School-supplied disclosures");break;
   case "cost-summary":case "monthly-cost":{
